{"title": "Cortex XDR incident lifecycle - at a glance", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": 2,
  "data": [
    {
      "name": "inc",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "incident"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.incident_id",
                    "size": 5000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.incident_id",
                            "data.cortex.incident_name",
                            "data.cortex.severity",
                            "data.cortex.status",
                            "data.cortex.is_resolved",
                            "data.cortex.assigned_user_pretty_name",
                            "data.cortex.alert_count",
                            "data.cortex.host_count",
                            "data.cortex.user_count",
                            "data.cortex.creation_time",
                            "data.cortex.resolved_timestamp",
                            "data.cortex.sla_hours"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex",
          "as": "c"
        },
        {
          "type": "formula",
          "expr": "(datum.c.is_resolved === 'true' || datum.c.is_resolved === true)",
          "as": "resolved"
        },
        {
          "type": "formula",
          "expr": "isNaN(toNumber(datum.c.creation_time)) ? toDate(datum.c.creation_time) : toDate(toNumber(datum.c.creation_time))",
          "as": "created"
        },
        {
          "type": "formula",
          "expr": "datum.resolved && datum.c.resolved_timestamp ? (isNaN(toNumber(datum.c.resolved_timestamp)) ? toDate(datum.c.resolved_timestamp) : toDate(toNumber(datum.c.resolved_timestamp))) : null",
          "as": "closed"
        },
        {
          "type": "formula",
          "expr": "toNumber(datum.c.sla_hours) || ({\"critical\": 4, \"high\": 8, \"medium\": 24, \"low\": 120})[datum.c.severity] || 120",
          "as": "sla"
        },
        {
          "type": "formula",
          "expr": "datum.closed ? (time(datum.closed) - time(datum.created)) / 3600000 : null",
          "as": "ttr"
        },
        {
          "type": "formula",
          "expr": "(now() - time(datum.created)) / 3600000",
          "as": "age"
        },
        {
          "type": "formula",
          "expr": "!datum.resolved && datum.age > datum.sla",
          "as": "overdue"
        },
        {
          "type": "formula",
          "expr": "datum.closed && now() - time(datum.closed) <= 30 * 86400000",
          "as": "recent"
        }
      ]
    },
    {
      "name": "open",
      "source": "inc",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.resolved"
        }
      ]
    },
    {
      "name": "late",
      "source": "open",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.overdue"
        }
      ]
    },
    {
      "name": "unassigned",
      "source": "open",
      "transform": [
        {
          "type": "filter",
          "expr": "!datum.c.assigned_user_pretty_name"
        }
      ]
    },
    {
      "name": "recent",
      "source": "inc",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.recent"
        }
      ]
    },
    {
      "name": "ontime",
      "source": "recent",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.ttr <= datum.sla"
        }
      ]
    },
    {
      "name": "mttr",
      "source": "recent",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "ttr"
          ],
          "ops": [
            "mean"
          ],
          "as": [
            "m"
          ]
        }
      ]
    },
    {
      "name": "asg",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "incident"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.incident_id",
                    "size": 5000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.creation_time"
                          ]
                        }
                      }
                    },
                    "unassigned": {
                      "filter": {
                        "bool": {
                          "must_not": {
                            "exists": {
                              "field": "data.cortex.assigned_user_pretty_name"
                            }
                          }
                        }
                      },
                      "aggs": {
                        "t": {
                          "min": {
                            "field": "timestamp"
                          }
                        }
                      }
                    },
                    "assigned": {
                      "filter": {
                        "exists": {
                          "field": "data.cortex.assigned_user_pretty_name"
                        }
                      },
                      "aggs": {
                        "t": {
                          "min": {
                            "field": "timestamp"
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex.creation_time",
          "as": "ct"
        },
        {
          "type": "formula",
          "expr": "isNaN(toNumber(datum.ct)) ? toDate(datum.ct) : toDate(toNumber(datum.ct))",
          "as": "created"
        },
        {
          "type": "filter",
          "expr": "datum.unassigned.t.value != null && datum.assigned.t.value != null && datum.assigned.t.value > datum.unassigned.t.value"
        },
        {
          "type": "formula",
          "expr": "(datum.assigned.t.value - time(datum.created)) / 3600000",
          "as": "tta"
        }
      ]
    },
    {
      "name": "tta",
      "source": "asg",
      "transform": [
        {
          "type": "aggregate",
          "fields": [
            "tta"
          ],
          "ops": [
            "mean"
          ],
          "as": [
            "m"
          ]
        }
      ]
    },
    {
      "name": "tiles",
      "values": [
        {
          "i": 0,
          "label": "Open incidents",
          "bad": false
        },
        {
          "i": 1,
          "label": "Open past SLA",
          "bad": true
        },
        {
          "i": 2,
          "label": "Unassigned open",
          "bad": true
        },
        {
          "i": 3,
          "label": "MTTR, last 30 days",
          "bad": false
        },
        {
          "i": 4,
          "label": "Resolved within SLA",
          "bad": false
        },
        {
          "i": 5,
          "label": "Time to assign, observed",
          "bad": false
        }
      ],
      "transform": [
        {
          "type": "formula",
          "expr": "datum.i === 0 ? (length(data('open'))) : datum.i === 1 ? (length(data('late'))) : datum.i === 2 ? (length(data('unassigned'))) : datum.i === 3 ? ((length(data('mttr')) && data('mttr')[0].m != null ? format(data('mttr')[0].m, '.1f') + ' h' : 'n/a')) : datum.i === 4 ? (length(data('recent')) ? format(length(data('ontime')) / length(data('recent')), '.0%') : 'n/a') : datum.i === 5 ? ((length(data('tta')) && data('tta')[0].m != null ? format(data('tta')[0].m, '.1f') + ' h' : 'n/a')) : 0",
          "as": "value"
        }
      ]
    }
  ],
  "marks": [
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.46"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "signal": "max(14, min(height * 0.42, width / 6 * 0.26))"
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "signal": "datum.bad && datum.value > 0 ? '#BD271E' : '#343741'"
          },
          "text": {
            "signal": "isString(datum.value) ? datum.value : format(datum.value, ',')"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "tiles"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "(datum.i + 0.5) * width / 6"
          },
          "y": {
            "signal": "height * 0.82"
          },
          "align": {
            "value": "center"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fill": {
            "value": "#69707D"
          },
          "text": {
            "field": "label"
          }
        }
      }
    }
  ]
}"}}

{"title": "Cortex XDR incident lifecycle - MTTR against SLA", "type": "vega", "aggs": [], "params": {"spec": "{
  "$schema": "https://vega.github.io/schema/vega/v5.json",
  "description": "Mean time to resolve per severity against its SLA target",
  "autosize": {
    "type": "fit",
    "contains": "padding"
  },
  "padding": {
    "left": 6,
    "right": 6,
    "top": 6,
    "bottom": 6
  },
  "data": [
    {
      "name": "inc",
      "url": {
        "%context%": true,
        "index": "wazuh-alerts-*",
        "body": {
          "size": 0,
          "aggs": {
            "scoped": {
              "filter": {
                "bool": {
                  "filter": [
                    {
                      "term": {
                        "data.integration": "cortex_xdr"
                      }
                    },
                    {
                      "term": {
                        "data.cortex.event_type": "incident"
                      }
                    }
                  ]
                }
              },
              "aggs": {
                "b": {
                  "terms": {
                    "field": "data.cortex.incident_id",
                    "size": 5000
                  },
                  "aggs": {
                    "latest": {
                      "top_hits": {
                        "size": 1,
                        "sort": [
                          {
                            "timestamp": {
                              "order": "desc"
                            }
                          }
                        ],
                        "_source": {
                          "includes": [
                            "data.cortex.incident_id",
                            "data.cortex.incident_name",
                            "data.cortex.severity",
                            "data.cortex.status",
                            "data.cortex.is_resolved",
                            "data.cortex.assigned_user_pretty_name",
                            "data.cortex.alert_count",
                            "data.cortex.host_count",
                            "data.cortex.user_count",
                            "data.cortex.creation_time",
                            "data.cortex.resolved_timestamp",
                            "data.cortex.sla_hours"
                          ]
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
      },
      "format": {
        "property": "aggregations.scoped.b.buckets"
      },
      "transform": [
        {
          "type": "formula",
          "expr": "datum.latest.hits.hits[0]._source.data.cortex",
          "as": "c"
        },
        {
          "type": "formula",
          "expr": "(datum.c.is_resolved === 'true' || datum.c.is_resolved === true)",
          "as": "resolved"
        },
        {
          "type": "formula",
          "expr": "isNaN(toNumber(datum.c.creation_time)) ? toDate(datum.c.creation_time) : toDate(toNumber(datum.c.creation_time))",
          "as": "created"
        },
        {
          "type": "formula",
          "expr": "datum.resolved && datum.c.resolved_timestamp ? (isNaN(toNumber(datum.c.resolved_timestamp)) ? toDate(datum.c.resolved_timestamp) : toDate(toNumber(datum.c.resolved_timestamp))) : null",
          "as": "closed"
        },
        {
          "type": "formula",
          "expr": "toNumber(datum.c.sla_hours) || ({\"critical\": 4, \"high\": 8, \"medium\": 24, \"low\": 120})[datum.c.severity] || 120",
          "as": "sla"
        },
        {
          "type": "formula",
          "expr": "datum.closed ? (time(datum.closed) - time(datum.created)) / 3600000 : null",
          "as": "ttr"
        },
        {
          "type": "formula",
          "expr": "(now() - time(datum.created)) / 3600000",
          "as": "age"
        },
        {
          "type": "formula",
          "expr": "!datum.resolved && datum.age > datum.sla",
          "as": "overdue"
        },
        {
          "type": "formula",
          "expr": "datum.closed && now() - time(datum.closed) <= 30 * 86400000",
          "as": "recent"
        }
      ]
    },
    {
      "name": "done",
      "source": "inc",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.recent"
        },
        {
          "type": "aggregate",
          "groupby": [
            "c.severity"
          ],
          "fields": [
            "ttr",
            "ttr"
          ],
          "ops": [
            "mean",
            "count"
          ],
          "as": [
            "m",
            "n"
          ]
        },
        {
          "type": "formula",
          "expr": "datum['c.severity']",
          "as": "severity"
        }
      ]
    },
    {
      "name": "targets",
      "source": "inc",
      "transform": [
        {
          "type": "filter",
          "expr": "datum.c.sla_hours != null"
        },
        {
          "type": "aggregate",
          "groupby": [
            "c.severity"
          ],
          "fields": [
            "created"
          ],
          "ops": [
            "argmax"
          ],
          "as": [
            "newest"
          ]
        },
        {
          "type": "formula",
          "expr": "toNumber(datum.newest.c.sla_hours)",
          "as": "s"
        },
        {
          "type": "formula",
          "expr": "datum['c.severity']",
          "as": "severity"
        }
      ]
    },
    {
      "name": "rows",
      "values": [
        {
          "severity": "critical",
          "sla": 4,
          "ord": 0
        },
        {
          "severity": "high",
          "sla": 8,
          "ord": 1
        },
        {
          "severity": "medium",
          "sla": 24,
          "ord": 2
        },
        {
          "severity": "low",
          "sla": 120,
          "ord": 3
        }
      ],
      "transform": [
        {
          "type": "lookup",
          "from": "done",
          "key": "severity",
          "fields": [
            "severity"
          ],
          "values": [
            "m",
            "n"
          ],
          "default": null
        },
        {
          "type": "lookup",
          "from": "targets",
          "key": "severity",
          "fields": [
            "severity"
          ],
          "values": [
            "s"
          ],
          "default": null
        },
        {
          "type": "formula",
          "expr": "datum.s || datum.sla",
          "as": "sla"
        },
        {
          "type": "formula",
          "expr": "datum.m == null ? 0 : datum.m / datum.sla",
          "as": "pct"
        },
        {
          "type": "formula",
          "expr": "({\"critical\": \"#BD271E\", \"high\": \"#E7664C\", \"medium\": \"#D6BF57\", \"low\": \"#54B399\", \"informational\": \"#98A2B3\", \"other\": \"#D3DAE6\"})[datum.severity]",
          "as": "hex"
        },
        {
          "type": "formula",
          "expr": "datum.sla >= 24 ? (datum.sla / 24) + ' d' : datum.sla + ' h'",
          "as": "target"
        },
        {
          "type": "formula",
          "expr": "datum.m == null ? 'no resolutions' : format(datum.m, '.1f') + ' h'",
          "as": "label"
        }
      ]
    }
  ],
  "scales": [
    {
      "name": "y",
      "type": "band",
      "domain": {
        "data": "rows",
        "field": "severity",
        "sort": {
          "op": "min",
          "field": "ord"
        }
      },
      "range": "height",
      "padding": 0.45
    },
    {
      "name": "x",
      "type": "linear",
      "domain": [
        0,
        1.5
      ],
      "range": [
        0,
        {
          "signal": "width - 150"
        }
      ],
      "clamp": true
    }
  ],
  "marks": [
    {
      "type": "text",
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "value": 0
          },
          "y": {
            "scale": "y",
            "field": "severity",
            "band": 0.5
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 12
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "field": "hex"
          },
          "text": {
            "signal": "upper(datum.severity)"
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "70"
          },
          "x2": {
            "signal": "70 + scale('x', 1)"
          },
          "y": {
            "scale": "y",
            "field": "severity"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "fill": {
            "value": "#EEF0F3"
          },
          "cornerRadius": {
            "value": 5
          }
        }
      }
    },
    {
      "type": "rect",
      "from": {
        "data": "rows"
      },
      "encode": {
        "enter": {
          "tooltip": {
            "signal": "{'Severity': datum.severity, 'Mean time to resolve': datum.label, 'SLA': datum.target, 'Resolved (30 days)': datum.n || 0}"
          }
        },
        "update": {
          "x": {
            "signal": "70"
          },
          "x2": {
            "signal": "70 + scale('x', datum.pct)"
          },
          "y": {
            "scale": "y",
            "field": "severity"
          },
          "height": {
            "scale": "y",
            "band": 1
          },
          "fill": {
            "signal": "datum.pct > 1 ? '#BD271E' : datum.hex"
          },
          "cornerRadius": {
            "value": 5
          }
        }
      }
    },
    {
      "type": "rule",
      "encode": {
        "update": {
          "x": {
            "signal": "70 + scale('x', 1)"
          },
          "x2": {
            "signal": "70 + scale('x', 1)"
          },
          "y": {
            "value": 0
          },
          "y2": {
            "signal": "height"
          },
          "stroke": {
            "value": "#69707D"
          },
          "strokeDash": {
            "value": [
              4,
              3
            ]
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "70 + scale('x', 1)"
          },
          "y": {
            "scale": "y",
            "field": "severity",
            "offset": -6
          },
          "align": {
            "value": "right"
          },
          "fontSize": {
            "value": 10
          },
          "fill": {
            "value": "#69707D"
          },
          "text": {
            "signal": "'SLA ' + datum.target"
          }
        }
      }
    },
    {
      "type": "text",
      "from": {
        "data": "rows"
      },
      "encode": {
        "update": {
          "x": {
            "signal": "width"
          },
          "y": {
            "scale": "y",
            "field": "severity",
            "band": 0.5
          },
          "align": {
            "value": "right"
          },
          "baseline": {
            "value": "middle"
          },
          "fontSize": {
            "value": 13
          },
          "fontWeight": {
            "value": "bold"
          },
          "fill": {
            "signal": "datum.pct > 1 ? '#BD271E' : '#343741'"
          },
          "text": {
            "field": "label"
          }
        }
      }
    }
  ]
}"}}

